fn ascetic_2aco_body(ctx: &Ctx, args: Vec<Val>) -> Result<Val, Stop> {
    ctx.mes("[Mother Mathilda]")?;
    if ctx.var("BaseJob").get()?.loosely_equals(&ctx.constant("JOB_NOVICE")?) {
        if ctx.var("job_acolyte_q").get()? == 7 {
            ctx.mes("I will send a carrier pigeon to the Prontera Sanctuary. When you return, the Priest there should already have received my message.")?;
            ctx.next()?;
            ctx.lines_as(
                "Mother Mathilda",
                args!["I will pray to God, and hope that you become an Acolyte soon."],
            )?;
            ctx.close_window()?;
            return Err(Stop::End);
        }
        if ctx.var("job_acolyte_q").get()? != 0 {
            if ctx.var("job_acolyte_q").get()? == 3 {
                ctx.mes("Ah, you must be one of the Acolyte applicants. I sincerely welcome you.")?;
                ctx.next()?;
                ctx.lines_as(
                    "Mother Mathilda",
                    args![
                        ((Val::from("What is your name? ") + ctx.call(Function::StrCharInfo, vec![Val::from(0)])?)
                            + Val::from("? Let's see... Ah, you're on my list."))
                    ],
                )?;
                ctx.next()?;
                ctx.lines_as(
                    "Mother Mathilda",
                    args![
                        ((Val::from("I will send a message to the Sanctuary confirming that you, ")
                            + ctx.call(Function::StrCharInfo, vec![Val::from(0)])?)
                            + Val::from(" visited me and completed your penance."))
                    ],
                )?;
                ctx.next()?;
                ctx.lines_as(
                    "Mother Mathilda",
                    args!["Please return to the Prontera Sanctuary and speak to the Priest in charge."],
                )?;
                ctx.close_window()?;
                ctx.call(
                    Function::SavePoint,
                    vec![Val::from("moc_fild07"), Val::from(35), Val::from(355), Val::from(1), Val::from(1)],
                )?;
                ctx.var("job_acolyte_q").set(Val::from(7))?;
                return Err(Stop::End);
            } else {
                ctx.lines(args![
                    "Ah...!",
                    "You must be one",
                    "of the Acolyte applicants.",
                    "I sincerely welcome you."
                ])?;
                ctx.next()?;
                ctx.lines_as(
                    "Mother Mathilda",
                    args![
                        "Now, what is your name?",
                        ((Val::from("") + ctx.call(Function::StrCharInfo, vec![Val::from(0)])?) + Val::from("? Let's see..."))
                    ],
                )?;
                ctx.next()?;
                ctx.lines_as("Mother Mathilda", args!["Hmm...", "It seems your name", "is not on my list..."])?;
                ctx.next()?;
                ctx.lines_as(
                    "Mother Mathilda",
                    args![
                        "Perhaps you should return to the Prontera Sanctuary and check the destination for your penance trial once again."
                    ],
                )?;
                ctx.close_window()?;
                return Err(Stop::End);
            }
        } else {
            ctx.mes("...")?;
            ctx.close_window()?;
            return Err(Stop::End);
        }
    } else {
        if ctx.var("BaseJob").get()?.loosely_equals(&ctx.constant("JOB_ACOLYTE")?) {
            shared::jobs_2_1_priest::f_mothermart(ctx, vec![])?;
        } else {
            if ctx.var("BaseJob").get()?.loosely_equals(&ctx.constant("JOB_PRIEST")?) {
                ctx.mes("Hello there~")?;
                ctx.next()?;
                ctx.lines_as(
                    "Mother Mathilda",
                    args!["How is your practice coming along? I certainly hope you're enjoying living in the grace of God."],
                )?;
                ctx.close_window()?;
                return Err(Stop::End);
            } else {
                ctx.lines(args!["May God", "be with you..."])?;
                ctx.close_window()?;
                return Err(Stop::End);
            }
        }
    }
    Ok(Val::from(0))
}

